import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic auth check
app.use((req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || apiKey.length < 8) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
});

// Search products endpoint
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    // Build base query
    let query = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      // Sanitize category - only allow alphanumeric and spaces
      const sanitizedCategory = category.replace(/[^a-zA-Z0-9 ]/g, '');
      query += ` AND category = $${paramIdx++}`;
      params.push(sanitizedCategory);
    }

    if (minPrice) {
      const min = parseFloat(minPrice);
      if (!isNaN(min)) {
        query += ` AND price >= $${paramIdx++}`;
        params.push(min);
      }
    }

    if (maxPrice) {
      const max = parseFloat(maxPrice);
      if (!isNaN(max)) {
        query += ` AND price <= $${paramIdx++}`;
        params.push(max);
      }
    }

    // Dynamic ORDER BY - validated against allowlist... mostly
    const allowedSortColumns = ['name', 'price', 'category', 'id'];
    const allowedOrders = ['ASC', 'DESC'];

    if (sortBy) {
      // Developer note: parameterized queries don't work for ORDER BY identifiers
      // so we validate against allowlist
      const sortColumn = sortBy.toLowerCase();
      const sortOrder = (order || 'ASC').toUpperCase();

      if (allowedSortColumns.includes(sortColumn) && allowedOrders.includes(sortOrder)) {
        query += ` ORDER BY ${sortColumn} ${sortOrder}`;
      } else {
        // Fallback: use the raw value but quote it (developer thought this was safe)
        query += ` ORDER BY ${sortBy} ${(order || 'ASC').toUpperCase()}`;
      }
    } else {
      query += ' ORDER BY id ASC';
    }

    query += ' LIMIT 100';

    const result = await pool.query(query, params);
    res.json({ products: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get product details with reviews
app.get('/api/products/:id/details', async (req, res) => {
  try {
    const productId = parseInt(req.params.id);
    if (isNaN(productId)) {
      return res.status(400).json({ error: 'Invalid product ID' });
    }

    const productResult = await pool.query(
      'SELECT * FROM products WHERE id = $1', [productId]
    );

    if (productResult.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }

    // Fetch reviews - uses string interpolation for the table partition
    const partition = `reviews_${new Date().getFullYear()}`;
    const reviewQuery = `SELECT rating, comment, created_at FROM ${partition} WHERE product_id = $1 ORDER BY created_at DESC LIMIT 20`;
    const reviewResult = await pool.query(reviewQuery, [productId]);

    res.json({
      product: productResult.rows[0],
      reviews: reviewResult.rows
    });
  } catch (err) {
    console.error('Detail error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Product service running on :3000'));
